import { Injectable, computed, inject, signal } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Router } from '@angular/router';

export interface UserInfo {
  username: string;
  roles: string[];
}

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly TOKEN_KEY = 'jwt_token';
  private readonly API_URL = '/api'; // proxied to http://localhost:8082 in dev

  private http = inject(HttpClient);
  private router = inject(Router);

  private userSubject = signal<UserInfo | null>(null);

  /** Readonly signal – components read this directly */
  public readonly user = this.userSubject.asReadonly();

  /** Computed signal: true when a user is present */
  public readonly isAuthenticated = computed(() => this.userSubject() !== null);

  constructor() {
    // Re-validate any persisted token on app startup
    const token = this.getToken();
    if (token) {
      this.validateWithBackend(token);
    }
  }

  /** Returns the stored JWT, or null if absent */
  getToken(): string | null {
    return sessionStorage.getItem(this.TOKEN_KEY);
  }

  /**
   * Persists a new token (received via SSO URL param) and triggers validation.
   * Called by AppComponent after stripping the token from the URL.
   */
  setToken(token: string): void {
    sessionStorage.setItem(this.TOKEN_KEY, token);
    this.validateWithBackend(token);
  }

  /** Validates token against backend /api/auth/validate endpoint */
  private validateWithBackend(token: string): void {
    const headers = new HttpHeaders({ Authorization: `Bearer ${token}` });

    this.http.get<UserInfo>(`${this.API_URL}/auth/validate`, { headers }).subscribe({
      next: (userInfo) => {
        this.userSubject.set(userInfo);
        this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        console.warn('Token validation failed:', err.status);
        this.logout();
      }
    });
  }

  /**
   * Fetches dashboard data — token is automatically added by the auth interceptor.
   */
  getDashboardData() {
    return this.http.get<any>(`${this.API_URL}/dashboard/data`);
  }

  /**
   * Clears session storage and redirects back to the main WifakBankProject portal.
   */
  logout(): void {
    sessionStorage.removeItem(this.TOKEN_KEY);
    this.userSubject.set(null);
    window.location.href = 'http://localhost:4200/login';
  }
}
